/**
 * The IdP: the OpenID Provider generated by @maronn-openid-connect/cli
 * (src/oidc-provider/), running on Cloudflare Workers with its data in D1.
 *
 * What this file adds to the generated app:
 * - the settings and signing keys from the Worker's vars and secrets
 * - the relying parties of OIDC_CLIENTS_JSON, written to D1 on the first
 *   request of each isolate (Workers reach D1 only while handling a request)
 * - the Japanese screens of src/views.tsx
 * - a landing page and a health check
 */
import { Hono } from 'hono';
import { createCachedSigningKeyProvider } from '@maronn-openid-connect/core';
import { parseClientsJson } from './clients.js';
import { landingPage } from './landing.js';
import type { OidcProviderOptions } from './oidc-provider/app.js';
import { applyOidc } from './oidc-provider/apply.js';
import { registerClient } from './oidc-provider/db/index.js';
import { d1Database } from './oidc-provider/db/instance.js';
import { registerDevelopmentUsers } from './oidc-provider/development.js';
import { rpInitiatedLogoutConfig } from './oidc-provider/features/rp-initiated-logout/config.js';
import { createSecretSigningKeyProvider } from './signing-keys.js';
import { japaneseViews } from './views.js';

export interface Bindings {
  DB: D1Database;
  /** The issuer: the public origin of this Worker, without a trailing slash. */
  ISSUER?: string;
  /** Secret. JSON array of RSA private JWKs (src/signing-keys.ts). */
  OIDC_SIGNING_KEYS?: string;
  /** Secret. JSON array of the relying parties (src/clients.ts). */
  OIDC_CLIENTS_JSON?: string;
  /** "1" registers testuser / otheruser (password "password"). Local development only. */
  REGISTER_DEVELOPMENT_USERS?: string;
}

type AppEnv = { Bindings: Bindings };

let signingKeySecret: string | undefined;
const signingKeyProvider = createCachedSigningKeyProvider(
  createSecretSigningKeyProvider(() => signingKeySecret),
  5 * 60_000,
);

let initialized: Promise<void> | undefined;

/** Writes the clients (and the development users when asked) to D1, once per isolate. */
function initialize(env: Bindings): Promise<void> {
  initialized ??= (async () => {
    const db = d1Database(env.DB);
    const clients = parseClientsJson(env.OIDC_CLIENTS_JSON);
    // registerClient() replaces an earlier registration of the same client_id
    // and writes the same rows for the same values, so isolates that start at
    // the same moment do not conflict.
    for (const client of clients.registrations) {
      await registerClient(db, client);
    }
    rpInitiatedLogoutConfig.postLogoutRedirectUris = clients.postLogoutRedirectUris;
    if (env.REGISTER_DEVELOPMENT_USERS === '1') {
      await registerDevelopmentUsers(db);
    }
  })().catch((error: unknown) => {
    initialized = undefined;
    throw error;
  });
  return initialized;
}

export function createIdpApp(issuer: string): Hono<AppEnv> {
  const app = new Hono<AppEnv>();

  app.use('*', async (c, next) => {
    signingKeySecret = c.env.OIDC_SIGNING_KEYS;
    try {
      await initialize(c.env);
    } catch (error) {
      console.error('[idp] setup failed:', error instanceof Error ? error.message : error);
      return c.text('IdP の初期化に失敗しました。サーバーログを確認してください。', 500);
    }
    await next();
    // The login, consent and logout screens must not be framed by another site.
    c.header('X-Frame-Options', 'DENY');
    c.header('X-Content-Type-Options', 'nosniff');
  });

  app.get('/', (c) => c.html(landingPage(issuer)));
  app.get('/health', (c) => c.json({ status: 'ok' }));

  const options: OidcProviderOptions = {
    config: {
      issuer,
      accessTokenExpiresIn: 3600,
      idTokenExpiresIn: 3600,
      accessTokenFormat: 'jwt',
    },
    signingKeyProvider,
    views: japaneseViews,
    // The relying parties call /token and /userinfo from their servers, so
    // browsers of other origins have no reason to reach them.
    corsOrigins: issuer,
  };
  applyOidc(app, options);

  return app;
}

/**
 * The issuer comes from the ISSUER var, which is readable once a request
 * arrives, so the app is created for the first request and then reused.
 */
const apps = new Map<string, Hono<AppEnv>>();

export default {
  fetch(request, env, ctx) {
    const issuer = (env.ISSUER ?? '').replace(/\/+$/, '');
    if (!issuer) {
      return new Response('ISSUER が設定されていません（wrangler.jsonc の vars）。', { status: 500 });
    }
    let app = apps.get(issuer);
    if (!app) {
      app = createIdpApp(issuer);
      apps.set(issuer, app);
    }
    return app.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Bindings>;
